<script>
document.addEventListener('DOMContentLoaded', function () {
    const select = document.getElementById('adminResultSession');
    const target = document.getElementById('adminResultsContent');
    const status = document.getElementById('adminResultsStatus');
    if (!select || !target) return;
    const endpoint = @json(route('admin.student.results.data', ['id' => $student->id]));
    let loading = false;
    select.addEventListener('change', async function () {
        if (loading) return;
        loading = true;
        select.disabled = true;
        target.setAttribute('aria-busy', 'true');
        target.style.opacity = '.55';
        if (status) status.textContent = 'Loading results…';
        try {
            const response = await fetch(endpoint + '?session=' + encodeURIComponent(select.value), { headers: { 'Accept': 'application/json' } });
            const data = await response.json();
            if (!response.ok) throw new Error(data.message || 'Unable to load results.');
            target.innerHTML = data.html;
            if (status) status.textContent = 'Showing ' + (select.value.toLowerCase() === 'all' ? 'All sessions' : select.value);
            const nextUrl = new URL(window.location.href);
            nextUrl.searchParams.set('session', select.value);
            window.history.replaceState(null, '', nextUrl.toString());
        } catch (error) {
            if (status) status.textContent = error.message;
        } finally {
            loading = false;
            select.disabled = false;
            target.style.opacity = '';
            target.removeAttribute('aria-busy');
        }
    });
});
</script>
